 private MiniPlayer219(){}
 static boolean isPlayer(Activity a){for(Class<?> c=a.getClass();c!=null;c=c.getSuperclass())if(c.getName().equals("com.sauzask.nicoid.NicoidVideoActivity"))return true;return false;}
 public static void track(Activity a){if(a==null)return;Application app=a.getApplication();if(app==null||application==app)return;if(application!=null)application.unregisterActivityLifecycleCallbacks(CALLBACKS);application=app;app.registerActivityLifecycleCallbacks(CALLBACKS);}
